<template>
  <div v-loading="booting" class="app-root">
    <main v-if="!user && !booting" class="login-layout"><section class="login-story"><div class="wordmark"><span class="brand-symbol">✚</span> 云医院 <small>CLOUD HIS</small></div><div><p class="eyebrow">CONNECTED CARE, EVERY DAY</p><h1>让每次就诊<br>有序衔接。</h1><p class="login-intro">连接窗口、诊室、医技与药房。<br>让信息随诊疗流转，让医护专注于患者。</p><div class="login-flow"><span>挂号</span><i>→</i><span>诊疗</span><i>→</i><span>医技</span><i>→</i><span>药房</span></div></div><span class="login-bottom">门诊管理系统 · 1.0</span></section><section class="login-form-wrap"><div class="login-form"><p class="eyebrow">STAFF ACCESS</p><h2>登录工作台</h2><p class="muted">使用医院分配的岗位账号登录</p><el-form @submit.native.prevent="login"><el-form-item label="账号"><el-input v-model.trim="credentials.username" autocomplete="username" placeholder="输入账号" prefix-icon="el-icon-user"/></el-form-item><el-form-item label="密码"><el-input v-model="credentials.password" type="password" autocomplete="current-password" show-password placeholder="输入密码" prefix-icon="el-icon-lock"/></el-form-item><el-button native-type="submit" type="primary" class="login-button" :loading="working">登录 <i class="el-icon-right"/></el-button></el-form><p class="login-help">初始账号由管理员创建；本地开发账号见项目 README。</p></div></section></main>
    <div v-else-if="user" class="workspace"><aside class="sidebar"><div class="wordmark"><span class="brand-symbol">✚</span><span>云医院<small>CLOUD HIS</small></span></div><div class="nav-label">门诊业务</div><button v-for="n in navigation" :key="n.id" :aria-label="n.name" class="nav-button" :class="{active:view===n.id}" @click="navigate(n.id)"><i :class="n.icon" aria-hidden="true"/><span>{{n.name}}</span><i v-if="view===n.id" class="el-icon-arrow-right"/></button><div class="sidebar-note"><span class="live-dot"/>业务服务已连接<small>患者信息按岗位授权访问</small></div></aside><div class="main-shell"><header class="topbar"><span class="breadcrumb">工作空间 <i class="el-icon-arrow-right"/> <b>{{currentTitle}}</b></span><div class="topbar-right"><span>{{today()}}</span><el-dropdown @command="accountAction"><span class="account"><span class="account-avatar">{{user.display_name.slice(0,1)}}</span>{{user.display_name}}<i class="el-icon-arrow-down"/></span><el-dropdown-menu slot="dropdown"><el-dropdown-item disabled>{{label(user.role_code)}}</el-dropdown-item><el-dropdown-item command="password">修改密码</el-dropdown-item><el-dropdown-item command="logout" divided>退出登录</el-dropdown-item></el-dropdown-menu></el-dropdown></div></header><div class="page-content"><div class="page-heading"><div><p class="eyebrow">CLOUD HOSPITAL / {{view.toUpperCase()}}</p><h1>{{currentTitle}}</h1><p>{{descriptions[view]}}</p></div><span class="role-chip"><span class="live-dot"/>{{label(user.role_code)}}</span></div>
      <Dashboard v-if="view==='dashboard'" :user="user" @navigate="navigate"/>
      <Registration v-if="view==='registration'" :catalog="catalog" @receipt="receipt=$event"/>
      <Clinic v-if="view==='clinic'" :catalog="catalog" :user="user"/>
      <Execution v-if="view==='execution'" :catalog="catalog" :user="user"/>
      <Pharmacy v-if="view==='pharmacy'" :catalog="catalog" @catalog-change="loadCatalog"/>
      <Admin v-if="view==='admin'" :catalog="catalog" :user="user" @catalog-change="loadCatalog"/>
    </div><footer class="app-footer"><span>云医院 HIS · 门诊管理</span><span>{{user.department_name||'综合工作台'}} / v1.0.0</span></footer></div></div>
    <Receipt :receipt="receipt" @close="receipt=null"/>
    <el-dialog title="修改登录密码" :visible.sync="passwordDialog" width="420px"><el-form label-position="top"><el-form-item label="原密码"><el-input v-model="password.old_password" type="password" show-password/></el-form-item><el-form-item label="新密码（至少10位）"><el-input v-model="password.new_password" type="password" show-password/></el-form-item></el-form><span slot="footer"><el-button @click="passwordDialog=false">取消</el-button><el-button type="primary" @click="changePassword">保存并重新登录</el-button></span></el-dialog>
  </div>
</template>
<script>
import {api,setCsrf,label,today} from './api';
import Dashboard from './pages/Dashboard.vue';import Registration from './pages/Registration.vue';import Clinic from './pages/Clinic.vue';import Execution from './pages/Execution.vue';import Pharmacy from './pages/Pharmacy.vue';import Admin from './pages/Admin.vue';import Receipt from './components/Receipt.vue';
const menus=[{id:'dashboard',name:'业务总览',icon:'el-icon-data-board',roles:[]},{id:'registration',name:'挂号收费',icon:'el-icon-bank-card',roles:['CASHIER']},{id:'clinic',name:'门诊诊疗',icon:'el-icon-notebook-2',roles:['DOCTOR']},{id:'execution',name:'医技工作站',icon:'el-icon-first-aid-kit',roles:['CHECK','LAB','TREAT']},{id:'pharmacy',name:'药房管理',icon:'el-icon-box',roles:['PHARMACY']},{id:'admin',name:'系统管理',icon:'el-icon-setting',roles:['ADMIN']}];
export default{components:{Dashboard,Registration,Clinic,Execution,Pharmacy,Admin,Receipt},data:()=>({booting:true,working:false,user:null,credentials:{username:'',password:''},catalog:{departments:[],staff:[],items:[],medicines:[]},view:'dashboard',receipt:null,passwordDialog:false,password:{old_password:'',new_password:''},descriptions:{dashboard:'关注当前业务进展，开始今天的门诊工作。',registration:'登记患者与挂号，管理收费、退费和费用记录。',clinic:'按本次就诊维护病历、申请、确诊与处方。',execution:'协同完成检查、检验和处置，及时回传执行结果。',pharmacy:'核对已缴费处方，管理发退药、库存和交易记录。',admin:'维护账号、医生排班、业务目录与操作审计。'}}),computed:{navigation(){return menus.filter(m=>!m.roles.length||this.user.role_code==='ADMIN'||m.roles.includes(this.user.role_code));},currentTitle(){return menus.find(m=>m.id===this.view)?.name||'业务总览';}},async created(){window.addEventListener('session-expired',this.expired);try{await this.session();}catch{}finally{this.booting=false;}},beforeDestroy(){window.removeEventListener('session-expired',this.expired);},methods:{label,today,async session(){const s=await api.get('/auth/session');setCsrf(s.csrf_token);this.user=s.user;if(this.user)await this.loadCatalog();},async login(){if(!this.credentials.username||!this.credentials.password)return this.$message.warning('请填写账号和密码');this.working=true;try{const s=await api.post('/auth/login',this.credentials);setCsrf(s.csrf_token);this.user=s.user;this.credentials.password='';this.view='dashboard';await this.loadCatalog();}catch{}finally{this.working=false;}},async loadCatalog(){this.catalog=await api.get('/catalog');},navigate(view){if(this.navigation.some(n=>n.id===view))this.view=view;},async expired(){this.user=null;this.view='dashboard';this.receipt=null;try{await this.session();}catch{}},async accountAction(command){if(command==='password'){this.password={old_password:'',new_password:''};this.passwordDialog=true;return;}try{await api.post('/auth/logout');this.user=null;await this.session();}catch{}},async changePassword(){if(this.password.new_password.length<10)return this.$message.warning('新密码至少10位');try{await api.post('/auth/password',this.password);this.passwordDialog=false;this.user=null;await this.session();this.$message.success('密码已更新，请重新登录');}catch{}}}};
</script>

